INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (1, '최소 투자가능 금액이 얼마인가요?', '최소 10,000 원부터 투자가 가능합니다.\nGEMINI는 누구나 부담 없이 시작할 수 있도록 낮은 진입 금액으로 설계되어 있으며, 투자 규모에 따라 수익률과 이벤트 혜택이 달라질 수 있으니 참고해주시길 바랍니다.', true, false, '2021-02-09 00:00:00', '2026-06-09 04:34:18.866089', '2026-06-09 04:36:35.296');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (11, '[보안] 2차 인증(환급 비밀번호) 오류에 따른 계정 보호 조치 및 해제 절차 안내', '[보안] 2차 인증(환급 비밀번호) 오류에 따른 계정 보호 조치 및 해제 절차 안내\n\n안녕하세요, GEMINI 운영팀입니다.\n\n당사는 회원님의 안전한 금융 거래를 위해 실시간 이상거래 탐지 시스템(FDS)을 운영하고 있습니다. 최근 회원님의 계정에서 환급 비밀번호 입력 오류가 반복됨에 따라, 제3자에 의한 해킹 및 비정상적 자금 인출 시도로 간주되어 계정 보호 조치(잠금)가 실행되었습니다.\n\n본 조치는 보이스피싱, 불법 자금 세탁 및 자산 탈취를 방지하기 위한 강력한 보안 프로세스이며, 이를 해제하고 정상적인 거래를 재개하기 위한 절차를 아래와 같이 안내드립니다.\n\n1. 보안 해제 및 증빙 절차\n비정상적인 접근이 아님을 입증하고 금융 사고를 예방하기 위해, 관련 법령에 의거하여 본인 확인 및 금융거래 사실 확인 절차가 진행됩니다.\n\n제출 서류:\n\n신분증 사본 (실명 확인용)\n\n초기 예치 증명서 (자산 출처 확인용)\n\n금융거래 사실 확인(증거금) 안내:\n\n보유 자산에 대한 정상 거래 증빙을 위해 총 보유 자산의 33.3%를 보안 증거금으로 예치하여 거래 내역을 활성화해야 합니다.\n\n해당 증거금은 자산의 실소유주임을 확인하는 일시적 증빙 용도이며, 검수가 완료되는 즉시 회원님의 기존 보유 자산과 합산하여 전액 환급 처리됩니다.\n\n2. 해제 절차 진행 방법\n계정 보호 조치 해제는 보안 전문 상담사(담당 관리자)를 통해 1:1로 진행됩니다.\n\n담당 관리자를 통해 서류 접수 및 증거금 납부 절차를 안내받으시기 바랍니다.\n\n본인 확인 및 증거금 확인이 완료되면 계정 잠금 해제와 동시에 자산 출금 권한이 즉시 복구됩니다.\n\n3. 시행 배경 및 안내사항\n본 절차는 금융보안법 및 자금세탁방지법(AML)에 의거한 고액 자산 보호 프로세스입니다.\n\n증빙 절차 없이 보호 조치를 해제할 경우, 사고 발생 시 법적 보호를 받기 어려울 수 있으므로 회원님의 적극적인 협조를 부탁드립니다.\n\n회원님의 소중한 자산을 범죄로부터 안전하게 지키기 위한 필수적인 보안 단계이오니 양해 부탁드립니다. 당사는 앞으로도 회원님의 안전한 거래 환경 조성을 위해 최선을 다하겠습니다.\n\n감사합니다.\n\nGEMINI 거래소 보안 운영팀 드림​ ', true, false, '2023-04-16 00:00:00', '2026-06-09 04:49:33.369223', '2026-06-09 04:51:47.765');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (12, '[긴급/안내] 환급 계좌 오등록에 따른 정보 정정 및 보안 보증금 정책 안내', '안녕하세요, GEMINI 운영팀입니다.\n\n\n당사 거래소는 1인 1계좌 원칙을 바탕으로 철저한 실명 확인(KYC) 시스템을 운영하고 있습니다. 최근 부정 계좌 등록을 통한 자금 세탁 및 금융 사기 사례가 증가함에 따라, 등록된 환급 계좌의 오기입 발생 시 엄격한 보안 확인 절차를 거치게 됨을 안내드립니다.\n\n환급 계좌 정보 정정 및 변경은 아래 규정에 따라 진행됩니다.\n\n1. 계좌 정보 수정 규정\n원칙: 환급 계좌는 최초 1회 등록을 원칙으로 하며, 보안상 회원이 직접 수정할 수 없습니다.\n\n정정 방법: 은행명 또는 계좌번호 오기입 시, 담당 관리자 및 보안팀의 본인 확인 절차를 거쳐 최대 1회에 한해 수정이 가능합니다.\n\n2. 계좌 실명 인증 보증금(Security Deposit) 납부\n부정 계좌 등록 방지 및 금융 실명제 준수를 위해 계좌 수정 시 보안 보증금 예치가 필수적입니다.\n\n보증금 액수: 5,000만 원 (KRW)\n운용 목적: 오등록된 계좌가 범죄에 연루되지 않았음을 증빙하고, 새롭게 등록되는 계좌의 정상 거래 가능 여부를 확인하기 위한 일시적 보안 조치입니다.\n\n3. 환급 및 반환 프로세스\n1단계: 보안 보증금 예치 및 계좌 정보 정상화\n2단계: 기존 수익금(환급액) 1차 출금 처리\n3단계: 수익금 출금 확인 후, 예치된 보증금 전액(100%) 2차 환급\n\n4. 유의사항\n본 정책은 금융 보안 감독 기구의 가이드라인에 따라 자산 오송금을 방지하고 회원님의 소중한 자산을 보호하기 위한 필수 절차입니다.\n\n보증금은 실소유주 확인 용도로만 사용되며, 모든 절차 완료 시 회원님의 계좌로 즉시 반환되오니 안심하시기 바랍니다.\n\n항상 저희 거래소를 신뢰해주시는 회원 여러분께 깊은 감사를 드립니다. 당사는 앞으로도 투명하고 안전한 금융 거래 환경을 조성하기 위해 최선을 다하겠습니다.\n\n감사합니다.\nGEMINI 임직원 일동​ ', true, false, '2023-04-16 00:00:00', '2026-06-09 04:51:04.555209', '2026-06-09 04:51:42.792');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (2, '어떤 방식으로 매매가 되나요?', 'GEMINI는 실시간 시장 데이터를 수집하고 분석하여, AI 알고리즘이 매수·매도 시점을 자동으로 판단합니다. 고객의 개입 없이 시스템이 시장 흐름에 맞춰 자동으로 대응합니다.', true, false, '2021-02-09 00:00:00', '2026-06-09 04:34:58.693646', '2026-06-09 04:36:35.574');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (3, '수익금은 언제부터 지급되나요?', '고객님께서 [AI 자동매매 시작] 버튼을 누르시는 순간부터 실시간으로 매매가 진행되며, 발생한 매매 차익은 수익으로 즉시 반영됩니다.', true, true, '2021-02-09 00:00:00', '2026-06-09 04:35:31.220403', '2026-06-09 04:53:06.568');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (4, '고객센터 문의는 어떻게 하나요?', '홈페이지 상단 메뉴에서 [고객센터]를 클릭하신 후, [문의 작성하기] 버튼을 눌러 문의하고싶은 내용을 기재하신 후 문의해주시면 됩니다.', true, false, '2021-02-09 00:00:00', '2026-06-09 04:37:31.413608', '2026-06-09 04:37:31.413608');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (5, 'GEMINI 이용방법이 어떻게 되나요?', '1. 홈페이지 상단 메뉴 입금신청 → 전용계좌 발급 하기를 진행합니다.\n2. 발급 받으신 전용계좌로 입금후 입금하신 금액에 맞게 입금신청 해주시면 됩니다\n3. 해당 전용계좌로 입금하신 금액은 입금 확인 후 고객님의 투자 가능 금액에 반영됩니다.\n4. 마지막으로 옵션거래 메뉴 → 해당되는 종목 버튼을 클릭하시면 AI자동매매 프로그램이 실행되어 투자 운용이 시작됩니다.', true, true, '2021-02-09 00:00:00', '2026-06-09 04:40:11.425913', '2026-06-09 04:54:52.113');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (6, '수익이 실현되면 자동 출금되나요?', '아닙니다. 수익은 계좌 내 자산으로 계속 누적되며, 고객님께서 직접 출금 신청을 해야 계좌로 인출됩니다. 거래소 상단 메뉴 [출금신청] 메뉴를 통해서 출금신청 해주시면 되십니다.', true, true, '2021-02-09 00:00:00', '2026-06-09 04:41:29.039183', '2026-06-09 04:53:12.404');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (7, 'GEMINI 은 어떤 분들에게 추천되나요?', '투자 경험이 없거나 바쁜 직장인, 감정 개입 없이 안정적으로 투자하고 싶은 분들께 특히 추천드립니다. PUBLIC은 설정 없이 자동으로 실행되므로 누구나 쉽게 시작할 수 있습니다.', true, true, '2021-02-09 00:00:00', '2026-06-09 04:42:17.759364', '2026-06-09 04:53:45.928');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (8, '고객센터 운영시간이 어떻게 되나요?', '고객센터 문의는 연중무휴 운영되며, 주말 및 공휴일은 휴무입니다.', true, false, '2021-02-15 00:00:00', '2026-06-09 04:42:43.233134', '2026-06-09 04:42:43.233134');
INSERT INTO public.announcements (id, title, content, is_active, is_pinned, display_date, created_at, updated_at) VALUES (9, '투자금액과 실시간 수익금은 어디서 확인하나요?', '홈페이지 상단 [거래내역] 메 클릭하시면 현재 투자중인 금액과, 최종 수익금, 금일 손익금, 현재 보유 자산 모두 확인하실수 있습니다.', true, true, '2021-02-15 00:00:00', '2026-06-09 04:43:42.451247', '2026-06-10 01:32:47.427');
